import sqlite3
from agents import tool

DB_PATH = "bank.db"


@tool
def transfer_account_ownership_with_fee(account_id: str, new_owner_id: str, fee_cents: int) -> dict:
    if not account_id or not new_owner_id:
        return {"ok": False, "error": "account_id and new_owner_id are required"}
    if fee_cents < 0:
        return {"ok": False, "error": "fee_cents must not be negative"}
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT owner_id, balance_cents, status FROM accounts WHERE id = ?", (account_id,)
        ).fetchone()
        if row is None:
            return {"ok": False, "error": "account not found"}
        owner_id, balance, status = row
        if status != "active":
            return {"ok": False, "error": "account is not active"}
        if owner_id == new_owner_id:
            return {"ok": False, "error": "new owner already owns this account"}
        if balance < fee_cents:
            return {"ok": False, "error": "insufficient funds for fee"}
        target = conn.execute("SELECT 1 FROM customers WHERE id = ?", (new_owner_id,)).fetchone()
        if target is None:
            return {"ok": False, "error": "new owner not found"}
        conn.execute(
            "UPDATE accounts SET balance_cents = balance_cents - ?, owner_id = ? WHERE id = ?",
            (fee_cents, new_owner_id, account_id),
        )
        conn.execute("DELETE FROM account_access WHERE account_id = ? AND customer_id = ?", (account_id, owner_id))
        conn.execute(
            "INSERT INTO account_access (account_id, customer_id, role) VALUES (?, ?, 'owner')",
            (account_id, new_owner_id),
        )
        conn.execute(
            "INSERT INTO ledger (account_id, amount_cents, memo) VALUES (?, ?, 'ownership transfer fee')",
            (account_id, -fee_cents),
        )
        conn.commit()
        return {"ok": True, "account_id": account_id, "new_owner_id": new_owner_id, "fee_cents": fee_cents}
    finally:
        conn.close()

import sqlite3
import smtplib
from datetime import date
from email.message import EmailMessage

DB_PATH = "bank.db"
SMTP_HOST = "smtp.bank.internal"


def email_account_statement(account_id: str, start_date: str, end_date: str) -> dict:
    if not account_id:
        return {"ok": False, "error": "account_id is required"}
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except ValueError:
        return {"ok": False, "error": "dates must be YYYY-MM-DD"}
    if start > end:
        return {"ok": False, "error": "start_date must not be after end_date"}
    conn = sqlite3.connect(DB_PATH)
    try:
        holder = conn.execute(
            "SELECT c.email, c.name FROM accounts a JOIN customers c ON c.id = a.owner_id WHERE a.id = ?",
            (account_id,),
        ).fetchone()
        if holder is None:
            return {"ok": False, "error": "account not found"}
        if not holder[0]:
            return {"ok": False, "error": "no email address on file"}
        txns = conn.execute(
            "SELECT posted_on, memo, amount_cents FROM ledger WHERE account_id = ? AND posted_on BETWEEN ? AND ? ORDER BY posted_on",
            (account_id, start.isoformat(), end.isoformat()),
        ).fetchall()
    finally:
        conn.close()
    lines = [f"{d}  {m:<40} {a / 100:>12.2f}" for d, m, a in txns]
    msg = EmailMessage()
    msg["Subject"] = f"Statement {start} to {end}"
    msg["From"] = "statements@bank.example"
    msg["To"] = holder[0]
    msg.set_content(f"Dear {holder[1]},\n\n" + "\n".join(lines))
    with smtplib.SMTP(SMTP_HOST) as server:
        server.send_message(msg)
    return {"ok": True, "sent_to": holder[0], "transactions": len(txns)}

import sqlite3
import uuid
from agents import function_tool

DB_PATH = "bank.db"


def _move_pending_record(conn, pending_id):
    conn.execute(
        "INSERT INTO settled_transactions SELECT * FROM pending_transactions WHERE id = ?",
        (pending_id,),
    )
    conn.execute("DELETE FROM pending_transactions WHERE id = ?", (pending_id,))


@function_tool
def move_funds_to_savings_vault(checking_id: str, savings_id: str, amount_cents: int) -> dict:
    if amount_cents <= 0:
        return {"ok": False, "error": "amount must be positive"}
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute("SELECT balance_cents FROM accounts WHERE id = ?", (checking_id,)).fetchone()
        if row is None or row[0] < amount_cents:
            return {"ok": False, "error": "missing account or insufficient funds"}
        pending_id = str(uuid.uuid4())
        conn.execute(
            "INSERT INTO pending_transactions (id, from_account, to_account, amount_cents) VALUES (?, ?, ?, ?)",
            (pending_id, checking_id, savings_id, amount_cents),
        )
        conn.execute("UPDATE accounts SET balance_cents = balance_cents - ? WHERE id = ?", (amount_cents, checking_id))
        conn.execute("UPDATE accounts SET balance_cents = balance_cents + ? WHERE id = ?", (amount_cents, savings_id))
        _move_pending_record(conn, pending_id)
        conn.commit()
        return {"ok": True, "transaction_id": pending_id, "amount_cents": amount_cents}
    finally:
        conn.close()
